1	import { spawnSync } from 'node:child_process';
2	import { readFileSync, writeFileSync, existsSync, statSync } from 'node:fs';
3	import { join, resolve, sep } from 'node:path';
4	import { parseEntries, sessionTranscriptPaths } from './session-transcript.mjs';
5	import { SHARED_SUBDIR, packEntryId } from '../../pack_loader/pack-registry.mjs';
6	import { SETTINGS_FILE, settingsPath } from '../../settings-file.mjs';
7	import { isVersion } from '../../version.mjs';
8	
9	function sh(root, cmd, args, { allowFail = false, input = undefined, timeout = undefined } = {}) {
10	  const r = spawnSync(cmd, args, { cwd: root, encoding: 'utf8', maxBuffer: 64 * 1024 * 1024, input, timeout });
11	  if (r.status !== 0 && !allowFail) {
12	    throw new Error(`${cmd} ${args.join(' ')} failed (${r.status}): ${r.stderr}`);
13	  }
14	  return r.status === 0 ? r.stdout : null;
15	}
16	
17	const git = (root, ...args) => sh(root, 'git', args);
18	const gitTry = (root, ...args) => sh(root, 'git', args, { allowFail: true });
19	
20	// The base branch this repo's work is judged against, in preference order.
21	// Exported because the CI entry point (../ci-work-scope.mjs) fetches these same
22	// refs before a context is built at all — one list, so what CI fetches and what a
23	// context resolves can never name different branches.
24	export const BASE_REF_CANDIDATES = ['origin/main', 'origin/master', 'main', 'master'];
25	
26	// All four candidates in ONE subprocess. `cat-file --batch-check` takes revisions on
27	// stdin and answers each independently — `<sha> commit <size>` for one that resolves,
28	// `<input> missing` for one that does not — so it is the same revision parser
29	// `rev-parse --verify` uses, `^{commit}` peeling included, asked four questions at
30	// once instead of four times. A repo whose base is a local `main` (every check fixture,
31	// and any clone without a remote) missed on both `origin/` candidates first and paid
32	// three spawns for an answer that now costs one.
33	function resolveBaseRef(root) {
34	  const answers = (sh(root, 'git', ['cat-file', '--batch-check'],
35	    { allowFail: true, input: `${BASE_REF_CANDIDATES.map((ref) => `${ref}^{commit}`).join('\n')}\n` }) || '')
36	    .split('\n');
37	  // Object-id length is the repo's hash algorithm's, not a constant — sha1 and sha256
38	  // repos both answer here, and only the `commit` word decides.
39	  return BASE_REF_CANDIDATES.find((_, i) => /^[0-9a-f]+ commit /.test(answers[i] ?? '')) ?? null;
40	}
41	
42	const FETCH_TIMEOUT_MS = 8000;
43	const FETCH_WINDOW_MS = 5 * 60_000;
44	
45	// A remote-tracking base ref is only as fresh as the last fetch, and a cloud session's
46	// clone freezes it at container-creation time — so every commit the base branch gained
47	// since lands inside `mergeBase..HEAD` and gets billed to the work. That is a wrong
48	// verdict, not a stale one: the delta rules (squash-merge-history above all, a *blocking*
49	// rule) report other people's commits as introduced by this change, and `--changed`
50	// widens to files the change never touched. Refreshing the ref once per run is what makes
51	// "the work" mean the work.
52	//
53	// Best-effort by construction — no network, no remote, a lock held, a slow server: the
54	// fetch fails or times out and the run continues against the ref as it stands, exactly as
55	// before this existed. It writes ONLY the remote-tracking ref (explicit refspec, no tags):
56	// no local branch, no index, no working tree, nothing the session could be surprised by.
57	// Set CLAUDINITE_CHECKS_NO_FETCH=1 to skip it (sealed sandboxes, or to pin a base).
58	//
59	// And it runs once per freshness window, not once per run: the Stop hook builds a context
60	// every turn with tracked changes, and the fetch is that path's dominant wall-clock cost
61	// (~0.7s healthy, 8s timeout when the network is not). A marker in the git dir records
62	// which ref was refreshed and when; a run inside the window trusts it and skips. The
63	// marker is PER-REF on purpose — a fetch of some other ref (or a marker left by one) says
64	// nothing about this base's freshness — and the staleness the window admits is the same
65	// class the fetch's own failure tolerance already accepts, now bounded by the window.
66	function refreshBaseRef(root, ref) {
67	  if (!ref || process.env.CLAUDINITE_CHECKS_NO_FETCH === '1') return;
68	  const m = /^([^/]+)\/(.+)$/.exec(ref);
69	  if (!m) return; // a local branch is already as current as the checkout — nothing to fetch
70	  const markerRel = (gitTry(root, 'rev-parse', '--git-path', 'claudinite-base-refresh.json') || '').trim();
71	  const marker = markerRel ? resolve(root, markerRel) : null;
72	  if (marker) {
73	    try {
74	      const last = JSON.parse(readFileSync(marker, 'utf8'));
75	      if (last.ref === ref && Date.now() - last.at < FETCH_WINDOW_MS) return;
76	    } catch { /* no marker (or an unreadable one) means no known freshness — fetch */ }
77	  }
78	  const [, remote, branch] = m;
