507	    // `version`. Omitting a declared key from this returned shape is the worst
508	    // kind of bug, legal to write and impossible to read: it is what made the
509	    // stamp invisible to the scheduler and silently killed baselining fleet-wide,
510	    // every repo self-skipping as "no vendored mount" while its runs went green.
511	    // The CONFIG_KEYS-survive-loadConfig test pins the whole set.
512	    engineVersion,
513	    packVersions,
514	    // The harsh override, normalized to the boolean every caller asks for and named
515	    // exactly as the file names it — one spelling, so nothing has to learn that the
516	    // key and the field it loads into are different words. Absent is the normal
517	    // shape and means the update PR lands on its own.
518	    dailyClaudiniteUpdatesRequirePrReview: requirePrReview,
519	    // The declaration exactly as the member wrote it. The engine normalizes what the
520	    // engine OWNS; a setting belonging to a pack is that pack's to read, and its
521	    // reader needs the unnormalized file — both to find a parameter on a pack entry
522	    // and to resolve a retired top-level spelling the engine deliberately no longer
523	    // folds. Every caller that has a shape to ask about should ask its owner's
524	    // predicate, not reach in here.
525	    raw,
526	    errors,
527	  };
528	}
529	
530	// One derivation, computed on first read and then remembered. Every work-scoping
531	// value below costs at least one git subprocess, and a run reads a handful of them:
532	// a Stop-hook sweep that only judges the session never asks for the merge-base, and
533	// a test that builds a context for one rule pays for the eight lists that rule never
534	// looks at. The memo keeps a re-read free, so a rule reading `ctx.files` twice still
535	// spawns `check-attr` once — exactly what the eager field did.
536	// Derive once, on first read. The flag is set AFTER the call, not before: a
537	// derivation that throws must throw again on the next read rather than be
538	// remembered as `undefined`, which is what the eager form did — it threw during
539	// buildContext and the run stopped there.
540	const once = (fn) => {
541	  let value, derived = false;
542	  return () => {
543	    if (!derived) { value = fn(); derived = true; }
544	    return value;
545	  };
546	};
547	
548	// Replace a lazy accessor with a plain value assigned over it. ESM is strict, so a
549	// getter with no setter turns `ctx.files = …` into a TypeError. Nothing in this repo
550	// assigns to one, but the engine is vendored into member repos whose own local packs
551	// this canon cannot see; the setter keeps such an assignment behaving exactly as it
552	// did against the eager data property instead of crashing that member's sweep.
553	const overwrite = (ctx, key, value) =>
554	  Object.defineProperty(ctx, key, { value, writable: true, enumerable: true, configurable: true });
555	
556	export function buildContext({ root, mode = 'changed', baseOverride = null, transcriptPath = null }) {
557	  root = resolve(root);
558	  // The base ref and its refresh are the one pair that stays eager. Building a
559	  // context is what makes the base branch current — that is the refresh's whole
560	  // contract, and a caller that discards the context still wanted it done. Making it
561	  // a side effect of reading `ctx.mergeBase` would move that contract instead of
562	  // deferring a cost.
563	  const baseRef = baseOverride || resolveBaseRef(root);
564	  refreshBaseRef(root, baseRef);
565	  const mergeBase = once(() => (baseRef ? (gitTry(root, 'merge-base', 'HEAD', baseRef) || '').trim() || null : null));
566	  // Diffing against HEAD keeps uncommitted work in scope even when no base branch resolves.
567	  const diffBase = () => mergeBase() || 'HEAD';
568	  // Is this commit already on the base branch? `--is-ancestor` exits non-zero for "no",
569	  // which gitTry surfaces as null. No base ref to compare against ⇒ nothing is known to
570	  // be on it, so nothing is filtered out.
571	  const onBaseBranch = (sha) =>
572	    !!baseRef && gitTry(root, 'merge-base', '--is-ancestor', sha, baseRef) !== null;
573	
574	  // The vendored corpus under the shared mount is canon-owned, never the
575	  // project's own code — structurally out of scope for every check, on any git
576	  // host and any checkout (deliberately not attribute-driven). The consumer's
577	  // own .claudinite/local/packs/ sits BESIDE the shared mount and stays fully
578	  // in scope.
579	  // git emits '/'-separated paths on every platform; SHARED_SUBDIR is joined
580	  // with the platform separator, so normalize before prefix-matching.
581	  const sharedPrefix = `${SHARED_SUBDIR.split(sep).join('/')}/`;
582	
583	  const { tracked, untracked } = listFiles(root);
584	  // Both diff lists come out of the one call, so whichever is read first pays for the
585	  // pair — as the eager form did.
586	  const diff = once(() => diffLists(root, diffBase(), mergeBase()));
587	  const vsBase = () => diff().vsBase;
588	  const deleted = () => diff().deleted;
589	  const scanned = once(() => (mode === 'all'
590	    ? [...tracked, ...untracked]
591	    : [...new Set([...vsBase(), ...untracked])]).filter((f) => !f.startsWith(sharedPrefix)));
592	  // Every in-scope regular file, vendored/generated included.
593	  const allFiles = once(() => scanned().filter((f) => existsSync(join(root, f)) && statSync(join(root, f)).isFile()));
594	  // The default sweep excludes vendored/generated files, so `ctx.files` is the
595	  // project's OWN authored code and every check skips them for free (see vendoredSet).
596	  const files = once(() => {
597	    const vendored = vendoredSet(root, allFiles());
598	    return allFiles().filter((f) => !vendored.has(f));
599	  });
600	  // The in-scope files the current change touched (vs the scoping base),
601	  // untracked included — the file set behind lines.mjs addedLines, for
602	  // check-the-work rules that judge the work rather than re-audit the world.
603	  const changedFiles = once(() => {
604	    const changedSet = new Set([...vsBase(), ...untracked]);
605	    return files().filter((f) => changedSet.has(f));
606	  });
607	
608	  const commits = once(() => {
609	    if (!mergeBase()) return [];
610	    const out = gitTry(root, 'log', '--format=%s%n%b%x00', `${mergeBase()}..HEAD`);
611	    return (out || '').split('\0').map((m) => m.trim()).filter(Boolean);
612	  });
613	
614	  const branch = once(() => (gitTry(root, 'rev-parse', '--abbrev-ref', 'HEAD') || '').trim());
615	
616	  // Conversation surface: the Stop hook forwards the session's transcript_path;
617	  // every other surface (CI, a manual run) has none, and conversation rules must
618	  // return [] when this is null. Parsed lazily and cached — most sweeps never ask.
619	  let conversationCache;
620	  let sessionEntriesCache;
621	
622	  // Checks are read-only over an immutable snapshot of the tree, so file and
623	  // base-blob reads are cached for the sweep: many rules re-read the same files,
624	  // and each readBase is otherwise a git subprocess.
625	  const readCache = new Map();
626	  const readBaseCache = new Map();
627	
628	  // The work-scoping fields are accessors over the memos above; `root`, `mode`,
629	  // `baseRef`, `tracked`, `untracked` and `config` stay plain values, being either
630	  // free or read by nearly every rule. Declaring each accessor in place keeps the
631	  // key order — and so `Object.keys`, a spread and `JSON.stringify` — what it was.
632	  return {
633	    root,
634	    mode,
635	    baseRef,
636	    get mergeBase() { return mergeBase(); },
637	    set mergeBase(v) { overwrite(this, 'mergeBase', v); },
638	    get files() { return files(); },
639	    set files(v) { overwrite(this, 'files', v); },
640	    get allFiles() { return allFiles(); },
641	    set allFiles(v) { overwrite(this, 'allFiles', v); },
642	    get changedFiles() { return changedFiles(); },
643	    set changedFiles(v) { overwrite(this, 'changedFiles', v); },
644	    tracked,
645	    untracked,
646	    get deleted() { return deleted(); },
647	    set deleted(v) { overwrite(this, 'deleted', v); },
648	    get commits() { return commits(); },
649	    set commits(v) { overwrite(this, 'commits', v); },
650	    get branch() { return branch(); },
651	    set branch(v) { overwrite(this, 'branch', v); },
652	    config: loadConfig(root),
653	
654	    exists: (path) => existsSync(join(root, path)),
655	    read(path) {
656	      if (!readCache.has(path)) {
657	        let text;
658	        try { text = readFileSync(join(root, path), 'utf8'); } catch { text = null; }
659	        readCache.set(path, text);
660	      }
661	      return readCache.get(path);
662	    },
663	
664	    // File content at the scoping base (the merge-base with the base branch), or
665	    // null if the file didn't exist there or no base resolves. Lets a delta
666	    // check compare structured state — e.g. a manifest's permission set — against
667	    // the baseline precisely, immune to text-diff line noise (JSON trailing
668	    // commas make appending an array element re-touch the previous line).
669	    readBase(path) {
670	      if (!mergeBase()) return null;
671	      if (!readBaseCache.has(path)) readBaseCache.set(path, gitTry(root, 'show', `${mergeBase()}:${path}`));
672	      return readBaseCache.get(path);
673	    },
674	
675	    // Added lines of one file relative to the scoping base (untracked file = every line).
676	    addedLines(file) {
677	      if (!tracked.includes(file)) {
678	        const text = this.read(file);
679	        return text === null ? [] : text.split('\n').map((t, i) => ({ line: i + 1, text: t }));
680	      }
681	      const out = gitTry(root, 'diff', '-U0', diffBase(), '--', file);
682	      const added = [];
683	      let lineNo = 0;
684	      for (const l of (out || '').split('\n')) {
685	        const hunk = /^@@ -\d+(?:,\d+)? \+(\d+)(?:,\d+)? @@/.exec(l);
686	        if (hunk) { lineNo = Number(hunk[1]); continue; }
687	        if (l.startsWith('+') && !l.startsWith('+++')) { added.push({ line: lineNo, text: l.slice(1) }); lineNo += 1; }
688	        else if (!l.startsWith('-')) lineNo += l ? 1 : 0;
689	      }
690	      return added;
691	    },
692	
693	    // The lines the change REMOVES from a tracked file, numbered as the base
694	    // had them — the diff's "-" side, the mirror of addedLines. A file the
695	    // base did not hold removed nothing.
696	    removedLines(file) {
697	      if (!mergeBase() || !tracked.includes(file)) return [];
698	      const out = gitTry(root, 'diff', '-U0', diffBase(), '--', file);
699	      const removed = [];
700	      let lineNo = 0;
701	      for (const l of (out || '').split('\n')) {
702	        const hunk = /^@@ -(\d+)(?:,\d+)? \+\d+(?:,\d+)? @@/.exec(l);
703	        if (hunk) { lineNo = Number(hunk[1]); continue; }
704	        if (l.startsWith('-') && !l.startsWith('---')) { removed.push({ line: lineNo, text: l.slice(1) }); lineNo += 1; }
705	        else if (!l.startsWith('+')) lineNo += l ? 1 : 0;
706	      }
707	      return removed;
708	    },
709	
710	    // Parsed transcript entries of the session driving this run, or null when no
711	    // transcript is available (see conversationCache above).
712	    conversation() {
713	      if (conversationCache !== undefined) return conversationCache;
714	      if (!transcriptPath || !existsSync(transcriptPath)) return (conversationCache = null);
715	      try { conversationCache = parseEntries(readFileSync(transcriptPath, 'utf8')); }
716	      catch { conversationCache = null; }
717	      return conversationCache;
718	    },
719	
720	    // Every entry the session wrote — the transcript above plus each subagent
721	    // stream beside it — for the rules that judge what the session DID: the
722	    // skills it loaded, the calls it made. `conversation()` stays the session
723	    // file alone, since that is where the owner's turns are. Empty on a surface
724	    // with no transcript, which `conversation()` is what distinguishes from a
725	    // session that did nothing.
726	    sessionEntries() {
727	      if (sessionEntriesCache === undefined) {
728	        sessionEntriesCache = sessionTranscriptPaths(transcriptPath).flatMap((path) => {
729	          // A stream unreadable mid-write costs its own entries, never the others'.
730	          try { return parseEntries(readFileSync(path, 'utf8')); } catch { return []; }
731	        });
732	      }
733	      return sessionEntriesCache;
734	    },
735	
736	    // The branch's own commits since the merge-base, oldest first, each with its
737	    // changed files and committer date — for rules about the ORDER work landed in
738	    // (ctx.commits keeps only messages). Merges excluded: their file list is
739	    // empty under --name-only and their content arrives via their parents.
740	    commitsWithFiles() {
741	      if (!mergeBase()) return [];
742	      const out = gitTry(root, 'log', '--reverse', '--no-merges', '--name-only',
743	        '--format=%x00%H%x1f%cI%x1f%s', `${mergeBase()}..HEAD`);
744	      const parsed = [];
745	      for (const block of (out || '').split('\0')) {
746	        if (!block.trim()) continue;
747	        const [head, ...rest] = block.trim().split('\n');
748	        const [sha, date, subject] = head.split('\x1f');
749	        parsed.push({ sha, date, subject, files: rest.map((f) => f.trim()).filter(Boolean) });
750	      }
751	      return parsed;
752	    },
753	
754	    // Merge commits the current change introduces — those on HEAD's first-parent
755	    // chain since the merge-base with the base branch (the squash-only effect
756	    // check, scoped to the work). Empty when no base resolves or the branch is
757	    // even with it; pre-existing merges already on the base are out of range.
758	    //
759	    // The range alone trusts the merge-base to be right, and it isn't always: a
760	    // shallow clone's grafted boundary or a criss-cross history can hand back a
761	    // merge-base that sweeps the base branch's own merges into the range. So each
762	    // candidate is confirmed against the base ref itself — a merge already on the
763	    // base branch was never introduced here, whatever the range says. Offline and
764	    // exact, and it holds when refreshBaseRef couldn't run.
765	    introducedMergeCommits() {
766	      if (!mergeBase()) return [];
767	      const out = gitTry(root, 'log', '--merges', '--first-parent', '--format=%h %s', `${mergeBase()}..HEAD`);
768	      return lines(out).map((l) => {
769	        const i = l.indexOf(' ');
770	        return { sha: l.slice(0, i), subject: l.slice(i + 1) };
771	      }).filter(({ sha }) => !onBaseBranch(sha));
772	    },
773	
774	    // Fixed-string search across tracked files; git grep exits 1 on no match.
775	    // The vendored shared mount is structurally out of the sweep (canon-owned,
776	    // never the project's own code — vendoring/DESIGN.md item 6), so it is
777	    // excluded here exactly as it is from the scanned file set above: a hit
778	    // inside it must never become a finding.
779	    grepTracked(needle) {
780	      const out = gitTry(root, 'grep', '-n', '-F', needle, '--', '.', `:(exclude)${sharedPrefix}`);
781	      return lines(out).map((l) => {
782	        const m = /^([^:]+):(\d+):(.*)$/.exec(l);
783	        return m ? { file: m[1], line: Number(m[2]), text: m[3] } : null;
784	      }).filter(Boolean);
785	    },
786	  };
787	}
788	
789	export const pathDepth = (p) => (p === '.' || p === '' ? [] : p.split(sep));
