1	// The SCAN half of fleet-add-missing-packs — the cross-repo question "what might a
2	// member want that it does not declare?".
3	//
4	// It is one of the task's two first stages, reached when `scan_for_needed_packs=true`
5	// (params.mjs); the other is force-add-packs.mjs, where the answer was decided by
6	// hand instead of fingerprinted. Both converge work-list issues IN THE MEMBER
7	// (protocol.mjs) and fire that member's own scheduler — the fan-out model (#749):
8	// the enforcer dispatches, the member executes, and the agent that confirms a
9	// suspicion is the member's own, with the repo checked out (which settles exactly
10	// the content-reading fingerprints this REST sweep must defer).
11	//
12	// The census asks "is this repo a MEMBER". Freshness asks "is that membership still
13	// MEANING anything". Both take the member's declared pack set as given. Neither ever
14	// asks whether that set still MATCHES the repo — and nothing else does either: a
15	// pack's `detect` fingerprint is consulted once, at bootstrap's `--init`, and never
16	// again. The update backfills the seeded packs and each declared pack's `requires`
17	// closure; it does not re-fingerprint. So a repo that grows into a pack after
18	// adoption — adds a package.json, a firebase.json, a Chrome manifest — is never told
19	// the pack exists, and the owner has to already know what to ask for.
20	//
21	// It is a SUSPICION, and the issue says so. The `pack-declaration` conformance check
22	// was deliberately retired (engine/checks/README.md) because declaring a pack is the
23	// project's call; a fit finding is the same claim in a weaker place — a
24	// recommendation the member's agent (then a reviewer) acts on, never an assertion
25	// the repo is wrong. An owner (or the member's agent) that closes the suspected
26	// issue `not planned` has given a standing answer: the scan stops suggesting to that
27	// repo rather than reopening weekly.
28	//
29	// Dependency-free (global fetch, Node 20+); read-only toward every member's TREE,
30	// and writes only the work-list issue + label in members with findings.
31	
32	import { paged, readDeclaration, isDormant, ensureLabel, labeledIssues } from '../../fleet-api.mjs';
33	import { undeclaredFits } from './fingerprint-fit.mjs';
34	import { fetchTree, makeRemoteEvaluator } from './remote-context.mjs';
35	import { LABEL, MARK, SUSPECTED_TITLE, REQUESTED_TITLE } from './protocol.mjs';
36	import { ensureMark, markedBody, remarkWorkList, otherOpenWorkList } from './mark-work-list.mjs';
37	import { closeSatisfiedRequest } from './force-add-packs.mjs';
38	
39	// --- the issue body (pure) ----------------------------------------------------
40	
41	// The issue is the durable record AND the member agent's work list, so it carries
42	// the evidence rather than a bare verdict: which packs, what each one is for, and
43	// the standing reminder that a fingerprint suspects rather than proves.
44	export function suspectedBody({ fits, undecided, packsById = new Map() }) {
45	  const lines = [
46	    'This repo carries file shapes that fingerprint packs its `.claudinite-settings.json`',
47	    'does not declare. A fingerprint only **suspects** a pack is wanted — declaring one is',
48	    "this project's call, which is why this is an issue and not a failing check.",
49	    '',
50	    '## Suspected packs',
51	    '',
52	  ];
53	  for (const id of fits) {
54	    const belongs = packsById.get(id)?.ruleRoutingGuidance?.belongs;
55	    lines.push(`- **\`${id}\`**${belongs ? ` — ${belongs}` : ''}`);
56	  }
57	  lines.push(
58	    '',
59	    'This repo\'s own **adopt-requested-packs** task acts on this list: its agent confirms',
60	    'each suspicion against the checkout, adopts what survives through the adopt-pack skill',
61	    '(one reviewed PR on this repo), and declines the rest with a reason here. To decline',
62	    'everything for good, close this issue `not planned` — that is a standing answer the',
63	    'weekly fleet scan honours rather than re-suggesting.',
64	  );
65	  if (undecided.length) {
66	    lines.push(
67	      '',
68	      '## Not decided from outside',
69	      '',
70	      'These fingerprints read file **contents**, which the fleet\'s REST sweep cannot settle',
71	      'within its read budget. The agent working this issue has the repo checked out and can',
72	      'answer them exactly — `localFits` in the enforcer-side task\'s `fingerprint-fit.mjs`:',
73	      '',
74	      ...undecided.map((u) => `- \`${u.id}\` — ${u.why}`),
75	    );
76	  }
77	  lines.push(
78	    '',
79	    'Converged weekly by the fleet\'s add-missing-packs scan: it closes this `completed` once',
80	    'the declaration carries the packs (or the shape stops suggesting them).',
81	  );
82	  return lines.join('\n');
83	}
84	
85	// --- per-member issue convergence ----------------------------------------------
86	
87	// Converge one member's SUSPECTED issue against this sweep's finding. Returns
88	// `{ action, openWork }`: `action` is a one-line report entry or null, `openWork` is
89	// whether the member ends the sweep with an open suspected work list (the signal the
90	// worker fires its scheduler on).
91	export async function convergeSuspectedIssue(gh, fullName, { fits, body }) {
92	  const { open, closed } = await labeledIssues(gh, fullName, LABEL);
93	  const existing = open.find((i) => i.title === SUSPECTED_TITLE);
94	
95	  if (!fits.length) {
96	    if (!existing) return { action: null, openWork: false };
97	    await gh(`/repos/${fullName}/issues/${existing.number}/comments`, {
98	      method: 'POST', body: { body: 'Closed by the fleet\'s add-missing-packs scan: this repo now declares every pack its shape fingerprints.' },
99	    });
100	    await gh(`/repos/${fullName}/issues/${existing.number}`, {
101	      method: 'PATCH', body: { state: 'closed', state_reason: 'completed' },
102	    });
103	    return { action: `closed #${existing.number} (${fullName}: fitted)`, openWork: false };
104	  }
105	
106	  if (existing) {
107	    // The suspected set can change between runs. Rewrite the body rather than
108	    // commenting: the issue is a work list, and a work list that has to be
109	    // reassembled from a comment thread is one nobody reads to the bottom of. The
110	    // member's own machine block survives the rewrite, and a body that really
111	    // changed clears the status — the re-ask (mark-work-list.mjs).
112	    const written = await remarkWorkList(gh, fullName, existing, markedBody(body, existing));
113	    return { action: written ? `updated #${existing.number} (${fullName})` : null, openWork: true };
114	  }
115	
116	  // A deliberate `not planned` close is a standing decline for this repo — reopening
117	  // it every week would be nagging about a decision already made.
118	  const prior = closed.filter((i) => i.title === SUSPECTED_TITLE)
119	    .sort((a, b) => new Date(b.closed_at) - new Date(a.closed_at))[0];
120	  if (prior && prior.state_reason === 'not_planned') return { action: null, openWork: false };
121	
122	  await ensureLabel(gh, fullName, LABEL, {
123	    color: '0E8A16',
124	    description: 'The fleet asks this repo to declare packs — adopted by the adopt-requested-packs task',
125	  });
126	  await ensureMark(gh, fullName);
127	  const { status, json } = await gh(`/repos/${fullName}/issues`, {
128	    method: 'POST',
129	    body: {
130	      title: SUSPECTED_TITLE,
131	      // Behind the member's other open work list, where it has one: two lists are
132	      // two items of one task, and nothing else serializes them.
133	      body: markedBody(body, null, { blockedBy: otherOpenWorkList(open, SUSPECTED_TITLE) }),
134	      labels: [LABEL, MARK],
135	    },
136	  });
137	  if (status !== 201) throw new Error(`creating the suspected-packs issue in ${fullName} returned ${status}`);
138	  return { action: `opened #${json.number} (${fullName})`, openWork: true };
139	}
140	
141	// --- the run summary (pure) ---------------------------------------------------
142	
143	// Full-roster reporting, the same property every claudinite-fleet-sheepdog sweep carries: every repo
144	// under the owner lands under exactly one state. "Fitted" (nothing suspected) is
145	// named as loudly as "has fits", because a reader cannot otherwise tell a member
146	// that came back clean from one that fell out of the report.
147	export function renderFitSummary({
148	  owner, home, canonRepo, packCount, findings, fitted, dormant, outOfScope, unknown, actions, fired,
149	  repoFilter = null,
150	}) {
151	  const undecidedCount = findings.reduce((n, f) => n + f.undecided.length, 0);
152	  return [
153	    `# Fleet pack-fit scan — ${owner}`,
154	    '',
155	    // A SCOPED scan measured part of the fleet, and every count below is a count of
156	    // that part. Saying so first is what keeps "nothing suspected" from reading as a
157	    // statement about the fleet when it was a statement about four repos.
158	    repoFilter ? `Scoped to **${repoFilter.length} named repo(s)**: ${repoFilter.join(', ')}` : '',
159	    // The denominator, stated. "Nothing suspected" means nothing against THIS corpus,
160	    // and a corpus that quietly shrank (the enforcer's own mount instead of canon, a
161	    // half-fetched clone) produces a clean report for the wrong reason.
162	    `Fingerprinted against **${packCount} canon pack(s)** from \`${canonRepo}\`.`,
163	    '',
164	    '| members with fits | fitted (nothing suspected) | schedulers fired | dormant | out of scope | unknown |',
165	    '| --- | --- | --- | --- | --- | --- |',
166	    `| ${findings.length} | ${fitted.length} | ${fired.length} | ${dormant.length} | ${outOfScope.length} | ${unknown.length} |`,
167	    '',
168	    findings.length
169	      ? `**Undeclared fits (work list placed in each repo):**\n${findings.map((f) => `- \`${f.repo}\` → ${f.fits.join(', ')}`).join('\n')}`
170	      : '**Undeclared fits:** none — every member declares what its shape suspects 🎉',
171	    fitted.length ? `**Fitted:** ${fitted.join(', ')}` : '',
172	    dormant.length ? `**Dormant (not swept — upkeep stopped on purpose):** ${dormant.join(', ')}` : '',
173	    outOfScope.length ? `**Out of scope:** ${outOfScope.join(', ')}` : '',
174	    undecidedCount
175	      ? `**Undecided fingerprints (content-reading, deferred to each member's own agent):** ${undecidedCount} across the fleet`
176	      : '',
177	    unknown.length ? `**UNKNOWN (could not be swept — fix the token/scope):** ${unknown.join('; ')}` : '',
178	    `**Not swept:** ${home} — the enforcer itself`,
179	    actions.length ? `**Issue actions:** ${actions.join('; ')}` : '**Issue actions:** none (converged)',
180	  ].filter(Boolean).join('\n');
181	}
182	
183	// --- the sweep ---------------------------------------------------------------
184	
185	// The scan stage, with the corpus and config already in hand — worker.mjs owns both.
186	// `repos` is null for the fleet-wide scan (`repos=all-covered-members`) or a list of
187	// qualified `owner/name` when the run was scoped; a scoped scan measures what it was
188	// asked to and asserts nothing about the rest.
189	//
190	// Returns `{ findings, unknown, toFire, actions, … }`; `toFire` is the members that
191	// end the sweep with an open work list — suspected from this scan, or a REQUESTED
192	// issue still outstanding from an earlier force (re-firing is the retry loop for a
193	// member whose earlier adoption run died). It does not throw on an unswept member:
194	// the worker decides what a partial picture means for the whole run.
195	export async function runScan({ gh, home, owner, canonRepo, exclude = new Set(), packs, repos = null }) {
196	  const packsById = new Map(packs.map((p) => [p.id, p]));
197	  const wanted = repos ? new Set(repos.map((n) => n.toLowerCase())) : null;
198	
199	  const mine = (await paged(gh, '/user/repos?affiliation=owner'))
200	    .filter((r) => r.owner.login.toLowerCase() === owner);
201	  if (mine.length === 0) {
202	    throw new Error(`enumeration returned no repos owned by ${owner} — wrong token user or scope; `
203	      + 'refusing to run a sweep that would read an empty fleet as a converged one');
204	  }
205	
206	  const findings = []; const fitted = []; const dormant = []; const outOfScope = []; const unknown = [];
207	  const actions = []; const toFire = [];
208	  for (const r of mine.sort((a, b) => a.name.localeCompare(b.name))) {
209	    const fullName = r.full_name.toLowerCase();
210	    if (fullName === home.toLowerCase()) continue; // the enforcer itself — named in the summary, not swept
211	    if (wanted && !wanted.has(fullName)) continue; // out of this run's scope; the filter is the report's subject line
212	    // An ignored repo is skipped before its declaration is read: the fleet claims
213	    // nothing about one, so it is named and nothing more.
214	    if (exclude.has(fullName)) { outOfScope.push(`${r.full_name} (ignored — config.exclude)`); continue; }
215	    if (r.archived || r.fork) { outOfScope.push(`${r.full_name} (${r.archived ? 'archived' : 'fork'})`); continue; }
216	
217	    let decl;
218	    try {
219	      decl = await readDeclaration(gh, r.full_name);
220	    } catch (e) {
221	      unknown.push(`${r.full_name} — ${e.message}`);
222	      continue;
223	    }
224	    // Coverage is the census's question, not this sweep's: an uncovered repo has no
225	    // declaration to add a pack to, and its adoption issue is already open elsewhere.
226	    if (decl === null) { outOfScope.push(`${r.full_name} (uncovered — the census's question)`); continue; }
227	    // A dormant member stopped its own upkeep on purpose. Recommending packs to it
228	    // would be work it has declared it is not doing.
229	    if (isDormant(decl)) { dormant.push(fullName); continue; }
230	
231	    let result;
232	    try {
233	      const { tracked, truncated } = await fetchTree(gh, r.full_name, r.default_branch);
234	      const evaluate = makeRemoteEvaluator(gh, r.full_name, r.default_branch, { tracked, truncated });
235	      result = await undeclaredFits({ packs, declared: decl.packs ?? [], evaluate });
236	    } catch (e) {
237	      unknown.push(`${r.full_name} — ${e.message}`);
238	      continue;
239	    }
240	
241	    let requestOutstanding = false;
242	    try {
243	      const body = suspectedBody({ ...result, packsById });
244	      const { action, openWork } = await convergeSuspectedIssue(gh, r.full_name, { fits: result.fits, body });
245	      if (action) actions.push(action);
246	      // The satisfied-request close rides the same per-member visit: completion is a
247	      // fact about the member's declaration, whichever run opened the request.
248	      const { open } = await labeledIssues(gh, r.full_name, LABEL);
249	      const closed = await closeSatisfiedRequest(gh, r.full_name, { decl, open });
250	      if (closed) actions.push(closed);
251	      requestOutstanding = !closed && open.some((i) => i.title === REQUESTED_TITLE);
252	      if (openWork || requestOutstanding) {
253	        toFire.push({ fullName: r.full_name, defaultBranch: r.default_branch });
254	      }
255	    } catch (e) {
256	      unknown.push(`${r.full_name} — work-list convergence failed: ${e.message}`);
257	      continue;
258	    }
259	
260	    if (result.fits.length) findings.push({ repo: fullName, ...result });
261	    else fitted.push(fullName);
262	  }
263	
264	  return {
265	    findings, unknown, toFire, actions, fitted, dormant, outOfScope,
266	    summaryArgs: { owner, home, canonRepo, packCount: packs.length, findings, fitted, dormant, outOfScope, unknown, actions, repoFilter: repos },
267	  };
268	}
