1	// The full canon pack corpus, fetched — because the enforcer's own mount does not
2	// have it.
3	//
4	// THE TRAP this exists to avoid. A consumer's `.claudinite/shared/` carries the
5	// vendor set for the packs that consumer DECLARES, and nothing more: a claudinite-fleet-sheepdog repo
6	// declaring `basics` + `claudinite-fleet-sheepdog` mounts four packs. Calling `discoverPacks()` from
7	// inside the mount would therefore hand the fit sweep four fingerprints to test the
8	// whole fleet against, and every member would come back perfectly fitted — a green
9	// report produced by looking at almost nothing. That failure is silent by
10	// construction, which is the worst kind, so the corpus is fetched explicitly and the
11	// count is reported.
12	//
13	// Fetching canon also makes the fingerprints CURRENT rather than as-of the enforcer's
14	// last update. A pack added to canon this week is one the fleet should be measured
15	// against this week; the enforcer's mount would not carry it at all.
16	//
17	// A shallow clone, into a scratch dir, discarded when the process exits. The packs
18	// are loaded by importing THAT CLONE's pack-registry: `canonRoot` is derived from the
19	// registry module's own location, so the clone's registry scans the clone's packs/
20	// while the mount's registry keeps scanning the mount. Nothing here mutates the
21	// enforcer's checkout.
22	
23	import { execFileSync } from 'node:child_process';
24	import { mkdtempSync, existsSync } from 'node:fs';
25	import { tmpdir } from 'node:os';
26	import { join } from 'node:path';
27	import { pathToFileURL } from 'node:url';
28	import { removeTree } from '../../../../engine/remove-tree.mjs';
29	
30	// Below this, the corpus we loaded is not plausibly the canon and a "nothing
31	// suspected" verdict would be an artifact of the fetch rather than a fact about the
32	// fleet. The real number is dozens; this is a floor that catches an empty or
33	// half-cloned tree, not a assertion about corpus size.
34	const MIN_PLAUSIBLE_PACKS = 5;
35	
36	// Where canon is served from. A parameter rather than a constant because a fleet on
37	// GitHub Enterprise has its own host — and because it is what lets this be exercised
38	// against a real clone in tests without a network.
39	export const DEFAULT_ORIGIN = 'https://github.com';
40	
41	// The clone URL, with the token embedded for an https origin (the only kind that
42	// needs one). Never logged, never returned — callers get the packs, not the
43	// credential.
44	function cloneUrl(repo, token, origin) {
45	  if (!origin.startsWith('https://')) return `${origin}/${repo}.git`;
46	  return `https://x-access-token:${token}@${origin.slice('https://'.length)}/${repo}.git`;
47	}
48	
49	// Returns { packs, dispose } — call dispose() when done to remove the scratch clone.
50	// Throws on anything that would leave the sweep measuring the fleet against a partial
51	// corpus: a failed clone, a missing packs/ tree, a manifest that would not load.
52	export async function loadCanonPacks({ canonRepo, token, ref = null, origin = DEFAULT_ORIGIN } = {}) {
53	  if (!canonRepo || !canonRepo.includes('/')) {
54	    throw new Error(`canonRepo ${JSON.stringify(canonRepo)} is not an owner/repo — the fit sweep has no corpus to fingerprint against`);
55	  }
56	  const dir = mkdtempSync(join(tmpdir(), 'claudinite-canon-'));
57	  const dispose = () => { try { removeTree(dir); } catch { /* scratch */ } };
58	  try {
59	    // Shallow, single-branch, no blobs we don't need: the manifests and the modules
60	    // they import are all that gets read.
61	    const args = ['clone', '--depth', '1', '--quiet'];
62	    if (ref) args.push('--branch', ref);
63	    args.push(cloneUrl(canonRepo, token, origin), dir);
64	    try {
65	      execFileSync('git', args, { stdio: ['ignore', 'ignore', 'pipe'] });
66	    } catch (e) {
67	      // The token is in the URL, so the raw git error is not safe to surface whole.
68	      const stderr = String(e.stderr ?? '').split(token).join('***');
69	      throw new Error(`cloning canon (${canonRepo}) failed: ${stderr.trim().split('\n').pop() || e.message}`);
70	    }
71	
72	    const registry = join(dir, 'engine/pack_loader/pack-registry.mjs');
73	    if (!existsSync(registry)) {
74	      throw new Error(`${canonRepo} has no engine/pack_loader/pack-registry.mjs — that is not a Claudinite canon`);
75	    }
76	    const { discoverPacks } = await import(pathToFileURL(registry).href);
77	    // No localRoot: a local pack belongs to one repo and is never fingerprinted.
78	    const { packs, errors } = await discoverPacks();
79	    if (errors.length) {
80	      throw new Error(`canon's pack corpus did not load cleanly (${errors.length} error(s)): ${errors.map((e) => e.what).join('; ')}`);
81	    }
82	    if (packs.length < MIN_PLAUSIBLE_PACKS) {
83	      throw new Error(`only ${packs.length} pack(s) loaded from ${canonRepo} — refusing to sweep the fleet against a corpus that small, `
84	        + 'because every member would report as fitted for the wrong reason');
85	    }
86	    return { packs, dispose };
87	  } catch (e) {
88	    dispose();
89	    throw e;
90	  }
91	}
