import { pathToFileURL } from 'node:url';
import { join } from 'node:path';

const canonDir = process.argv[2];
const repoRoot = process.argv[3];

const { discoverPacks } = await import(pathToFileURL(join(canonDir, 'engine/pack_loader/pack-registry.mjs')).href);
const { buildContext } = await import(pathToFileURL(join(canonDir, 'engine/checks/helpers/repo-context.mjs')).href);
const { localFits } = await import(pathToFileURL(join(canonDir, 'packs/claudinite-fleet-sheepdog/tasks/fleet-add-missing-packs/fingerprint-fit.mjs')).href);

const { packs, errors } = await discoverPacks();
if (errors.length) {
  console.error('discoverPacks errors:', errors);
  process.exit(1);
}
console.error(`loaded ${packs.length} canon packs`);

const ctx = buildContext({ root: repoRoot, mode: 'all' });
const declared = ctx.config.packEntries ?? [];

const targets = ['headless-browser', 'jwt', 'leaflet', 'web-speech'];
const targetPacks = packs.filter((p) => targets.includes(p.id));
console.error('target packs found:', targetPacks.map((p) => p.id));

const result = await localFits({ ctx, packs: targetPacks, declared });
console.log(JSON.stringify(result, null, 2));

