1	import { copyFileSync, mkdirSync, readFileSync, writeFileSync, existsSync } from 'node:fs';
2	import { join, dirname } from 'node:path';
3	import { fileURLToPath, pathToFileURL } from 'node:url';
4	import { computeVendorSet, copyIntoMount, SHARED_SUBDIR } from '../../../vendoring/compute-vendor-set.mjs';
5	import { loadPacks, resolveDeclaredPacks, packEntryId } from '../../../engine/pack_loader/pack-registry.mjs';
6	import { ENGINE_VERSION } from '../../../engine/version.mjs';
7	import { isVersion, versionAbove } from '../../../engine/version.mjs';
8	import { DECLARATION_FILE, migrationDirs, flowOf, recordVersion } from '../../../engine/checks/helpers/active-migrations.mjs';
9	import { settingsPath } from '../../../engine/settings-file.mjs';
10	import { installedVersions, hasInstalledMount, withInstalledVersions } from '../../../engine/installed-versions.mjs';
11	import { NEEDS_HUMAN, runSelfTest, deliveryDecision } from './engine-update.mjs';
12	import { isPackFile } from './pack-update.mjs';
13	
14	// INSTALL = THE UPDATE FLOW FROM VERSION ZERO (docs/versioned-updates/DESIGN.md §4),
15	// with one difference that is not an optimisation but a correctness rule:
16	//
17	//   **AN INSTALL RUNS NO MIGRATIONS** (owner decision 9). The vendored content is
18	//   already the newest shape, so there is no older state to migrate. Replaying
19	//   history onto a fresh install is not merely wasted work — a record assumes the
20	//   shapes ITS ERA produced, and an empty repo is not one of them, so the replay is
21	//   a hazard. The install fetches no records and stamps the LATEST version directly;
22	//   migrations exist for repos installed at an older one.
23	//
24	// Everything else is the pack flow's: same vendor set, same self-test gate, same
25	// terminals. What differs is only where it starts.
26	//
27	// AN INSTALL IS NOT AN UPDATE IN DISGUISE. A pack the repo already has a version for
28	// is refused rather than reinstalled: reinstalling would stamp the newest version
29	// while skipping every record between, which is exactly how a member ends up
30	// claiming a state it was never migrated into.
31	const canonRoot = dirname(dirname(dirname(dirname(fileURLToPath(import.meta.url))))); // <canon>/packs/claudinite-lifecycle/updates/<this file>
32	
33	const outcome = (status, detail, extra = {}) => ({ status, detail, ...extra });
34	
35	// Which of the requested ids this repo can actually install, and why the rest are
36	// refused. Pure over the pack set and the stamp, so the judgment is testable with
37	// no repo on disk.
38	export function planInstall(packs, ids, installed, { engineVersion = ENGINE_VERSION } = {}) {
39	  const byId = new Map(packs.map((p) => [p.id, p]));
40	  const stamped = installed?.packVersions ?? {};
41	  const install = [];
42	  const refused = [];
43	  for (const id of ids ?? []) {
44	    const pack = byId.get(id);
45	    if (!pack) { refused.push({ id, why: `"${id}" names no canon pack` }); continue; }
46	    if (isVersion(stamped[id])) {
47	      refused.push({ id, why: `"${id}" is already installed at version ${stamped[id]} — that is an update, not an install` });
48	      continue;
49	    }
50	    const needs = pack.minEngineVersion;
51	    if (isVersion(needs) && versionAbove(needs, engineVersion)) {
52	      refused.push({ id, why: `"${id}" needs engine ${needs}; this repo runs engine ${engineVersion}` });
53	      continue;
54	    }
55	    install.push({ id, version: pack.version ?? null });
56	  }
57	  return { install, refused };
58	}
59	
60	// The questions this install cannot answer for the repo. An interview is not a
61	// special terminal (DESIGN §3.9) — unanswered questions end the run exactly like a
62	// red check does: PR open, `needs-human`, stop. It degrades gracefully to async,
63	// which is what the live-session adoption skill could never do.
64	export function unansweredQuestions(packs, entries) {
65	  const byId = new Map(packs.map((p) => [p.id, p]));
66	  const out = [];
67	  for (const entry of entries ?? []) {
68	    const id = packEntryId(entry);
69	    const pack = id === undefined ? undefined : byId.get(id);
70	    if (!pack?.questions?.length) continue;
71	    const answers = (typeof entry === 'object' && entry?.answers) || {};
72	    for (const q of pack.questions) {
73	      if (!q?.id || answers[q.id] !== undefined) continue;
74	      out.push({ pack: id, question: q.id, prompt: q.prompt ?? '' });
75	    }
76	  }
77	  return out;
78	}
79	
80	// Install `ids` into `targetRoot`: declare them, vendor their content, stamp their
81	// latest versions, gate, and report. `dryRun` judges everything and writes nothing.
82	export async function installPacks(targetRoot, ids, {
83	  today, dryRun = false, delivery = 'auto-merge', forceMergeOnRedCi = false, selfTestRun, packs: packSet,
84	} = {}) {
85	  const settingsFile = settingsPath(targetRoot);
86	  if (!existsSync(settingsFile)) {
87	    return outcome(NEEDS_HUMAN, `${targetRoot} has no ${DECLARATION_FILE} — adoption seeds the declaration first`);
88	  }
89	  let raw;
90	  try { raw = JSON.parse(readFileSync(settingsFile, 'utf8')); }
91	  catch (e) { return outcome(NEEDS_HUMAN, `${DECLARATION_FILE} is not valid JSON: ${e.message}`); }
92	
93	  // Canonicalized by the shape reader before planInstall sees it: a renamed pack whose
94	  // version sits under the old key would otherwise be "not installed", and installing
95	  // re-stamps it at latest having run none of the records in its gap.
96	  const installed = hasInstalledMount(raw) ? installedVersions(raw) : null;
97	  const engineVersion = isVersion(installed?.engineVersion) ? installed.engineVersion : ENGINE_VERSION;
98	  // `packs` is injectable for the same reason `selfTestRun` is: the seed-op path is
99	  // only reachable through a manifest that declares one, and the canon deliberately
100	  // has none yet.
101	  const packs = packSet ?? await loadPacks();
102	  const { install, refused } = planInstall(packs, ids, installed, { engineVersion });
103	  if (!install.length) {
104	    return outcome(NEEDS_HUMAN, refused.map((r) => r.why).join('; ') || 'nothing to install', { refused });
105	  }
106	
107	  // The declaration first: the vendor set is computed FROM it, so a pack that is not
108	  // declared has no content to lay down.
109	  const declared = Array.isArray(raw.packs) ? [...raw.packs] : [];
110	  for (const { id } of install) {
111	    if (!declared.some((e) => packEntryId(e) === id)) declared.push(id);
112	  }
113	
114	  const entries = resolveDeclaredPacks(declared, packs);
115	
116	  // THE `requires` CLOSURE IS INSTALLED TOO, and stamped. A pack pulled in by another
117	  // (git-github via basics) has its content vendored either way — `computeVendorSet`
118	  // resolves the same closure — so stamping only the ids a caller happened to NAME
119	  // would leave the rest installed-but-unversioned. That is the same silent hole this
120	  // CLI was written to close, one level down: unversioned means the update flow reads
121	  // `from: null` and falls back to the landed-date window instead of comparing
122	  // numbers. A repo's real stamp already reflects this — the canary carries
123	  // `git-github: 1` without declaring it — so the arithmetic here is catching up with
124	  // what the fleet has always meant.
125	  const named = new Set(install.map((i) => i.id));
126	  const pulled = entries.map(packEntryId).filter((id) => typeof id === 'string' && !named.has(id));
127	  install.push(...planInstall(packs, pulled, installed, { engineVersion }).install);
128	
129	  // THE INTERVIEW COVERS WHAT THIS INSTALL ADDS, never a pack the repo declared on an
130	  // earlier day: what that adoption left unanswered is its own gap, and ending this
131	  // run `needs-human` on it would refuse every later pack to a repo with one old
132	  // unanswered question — while the adoption checks already hold that a pack in the
133	  // base is not re-litigated.
134	  const installing = new Set(install.map((i) => i.id));
135	  const unanswered = unansweredQuestions(packs, entries.filter((e) => installing.has(packEntryId(e))));
136	
137	  // No `installed` passed: an install fetches no migration records at all, whatever
138	  // the repo's stamp says. The set is content only.
139	  const inEffect = versionsInEffect(packs);
140	  const { files, errors } = await computeVendorSet(declared, { today, installed: { engineVersion, packVersions: inEffect } });
141	  if (errors.length) return outcome(NEEDS_HUMAN, errors.map((e) => e.what).join('; '), { errors, refused });
142	
143	  const ourFiles = files.filter((f) => install.some(({ id }) => isPackFile(f, id)));
144	  const records = ourFiles.filter((f) => f.includes('/migrations/'));
145	  if (dryRun) {
146	    return outcome('ok', `would install ${install.map((i) => i.id).join(', ')}`,
147	      { install, refused, unanswered, files: ourFiles.length, records: records.length, dryRun: true });
148	  }
149	
150	  const sharedDir = join(targetRoot, SHARED_SUBDIR);
151	  for (const file of ourFiles) {
152	    copyIntoMount(file, sharedDir);
153	  }
154	
155	  // Stamp the LATEST version directly — the install's whole claim. Nothing is
156	  // migrated into it, so nothing may imply it was.
157	  const next = JSON.parse(readFileSync(settingsFile, 'utf8'));
158	  // THE RESOLVED ENTRIES, not the bare `declared` list: every pack this run stamps
159	  // needs an entry to carry its version, and a pack pulled in through another's
160	  // `requires` is installed exactly as much as a named one. That is not a
161	  // declaration made on the repo's behalf — `via` is what says so, written by
162	  // `resolveDeclaredPacks` and read by anything that must tell a chosen pack from an
163	  // inferred one. It is also what `--init` already seeds, so the two writers agree.
164	  //
165	  // Before #1252 the closure's versions lived in a central map that needed no entry,
166	  // which is why the two could disagree at all: a pack could be installed, stamped,
167	  // and named nowhere in the file it was stamped in.
168	  next.packs = entries;
169	  const packVersions = {};
170	  for (const { id, version } of install) if (version !== null) packVersions[id] = inEffect[id];
171	  writeFileSync(settingsFile, `${JSON.stringify(withInstalledVersions(next, { packVersions }), null, 2)}\n`);
172	
173	  // Seed ops: the install-only effects the repo owns from here (DESIGN §4). Written
174	  // ONLY when the dest is absent — a seeded file is the member's from the moment it
175	  // lands, and an install that overwrote one would be doing exactly what the
176	  // seeded-vs-converged distinction exists to prevent.
177	  const seeded = [];
178	  for (const { id } of install) {
179	    const pack = packs.find((p) => p.id === id);
180	    for (const { template, dest } of pack?.seedOps ?? []) {
181	      const from = join(canonRoot, 'packs', id, template);
182	      const to = join(targetRoot, dest);
183	      if (!existsSync(from) || existsSync(to)) continue;
184	      mkdirSync(dirname(to), { recursive: true });
185	      copyFileSync(from, to);
186	      seeded.push(dest);
187	    }
188	  }
189	
190	  // Steps only a human can perform, collected from the packs actually installed
191	  // (`adoptionHandover`). Adoption is the one moment someone is present and the pack
192	  // is new, so this is where they get said; carrying them only in a pack's README
193	  // means the adopter meets them after the deploy has already failed.
194	  //
195	  // Reported, never acted on: nothing here can flip a repository setting, and a flow
196	  // that pretended to would be worse than one that names the gap.
197	  const handover = [];
198	  for (const { id } of install) {
199	    const pack = packs.find((p) => p.id === id);
200	    for (const step of pack?.adoptionHandover ?? []) handover.push({ pack: id, ...step });
201	  }
202	
203	  const selftest = runSelfTest(targetRoot, selfTestRun);
204	  const decision = unanswered.length
205	    ? { action: 'needs-human', why: `${unanswered.length} adoption question(s) unanswered: ${unanswered.map((u) => `${u.pack}/${u.question}`).join(', ')}` }
206	    : deliveryDecision({ selftestOk: selftest.ok, delivery, forceMergeOnRedCi });
207	
208	  return outcome(decision.action === 'needs-human' ? NEEDS_HUMAN : 'ok', decision.why, {
209	    install, refused, unanswered, seeded, handover, files: ourFiles.length, selftest, decision,
210	    // An install is where the pack's rules FIRST meet this repo's content, so the
211	    // apply stage is always the next step — there is no "nothing moved" case here.
212	    applyStage: { needed: true, packs: install.map((i) => i.id), why: 'the pack\'s rules meet this repo for the first time' },
213	  });
214	}
215	
216	// The version map that makes the record gate answer "nothing applies", and the number
217	// the install stamps: every pack at the newest version its content is IN EFFECT at.
218	// That is its manifest's number — or a pending record's, where one names a higher
219	// version. A record names the version main will cut after its merge (#1726, the bump
220	// is a task's and never the pull request's), so between that merge and the bump the
221	// manifest reads one number below the content it ships; a stamp taken off the
222	// manifest alone would then fetch the record into a fresh install, and the next
223	// converge would replay it onto a repo that already holds its result. Saying
224	// "nothing applies" through the same predicate the other flows use is better than a
225	// second code path that could drift from it.
226	//
227	// `records` is injectable for the unit test; the default is the corpus's own set.
228	export function versionsInEffect(packs, records = migrationDirs().map((dir) => ({ dir, version: recordVersion(dir) }))) {
229	  const current = Object.fromEntries(packs.map((p) => [p.id, p.version ?? 0]));
230	  for (const { dir, version } of records) {
231	    const { flow, pack } = flowOf(dir);
232	    if (flow !== 'pack' || !(pack in current)) continue;
233	    if (isVersion(version) && versionAbove(version, current[pack])) current[pack] = version;
234	  }
235	  return current;
236	}
237	
238	// CLI: `node install.mjs --target <dir> <pack-id>…` — install packs into a repo, from
239	// a fresh canon clone. Run by the adoption skills (adopt-pack, adopt-claudinite).
240	//
241	// WHY THIS EXISTS AT ALL (#768). The skills used to converge an adoption by hand:
242	// fetch canon, run `vendoring/apply-vendor-set.mjs`, advance the stamp. That lays the
243	// pack's FILES down correctly and gets one thing wrong that nothing notices for weeks
244	// — but not the thing this comment used to claim. `applyVendor` DOES write
245	// `claudinite.packVersions`; `computeVendorSet` returns the version of every declared
246	// pack and the writer stamps the lot in the same pass. The hazard is the opposite of
247	// "unversioned", and worse:
248	//
249	//   IT STAMPS EVERY DECLARED PACK AT THE NEWEST VERSION, whether or not the records
250	//   between were ever applied. `migrationApplies` is `want > have`, so the moment the
251	//   stamp reaches the record's own version the record stops applying — not for this
252	//   cycle, but forever. A member converged this way ends up CLAIMING a version whose
253	//   shape it was never migrated into, and nothing downstream can tell the difference,
254	//   because the stamp is the only thing that remembers.
255	//
256	// At version zero that is exactly right, and it is what an install means: no older
257	// state exists, so there is nothing to skip. Run it over a repo that already has a
258	// stamp and the same behaviour silently burns that repo's pending records — which is
259	// why `planInstall` refuses an already-installed pack rather than treating this as an
260	// optimisation (see the exit note at the bottom of `main`, which had this right).
261	//
262	// One runner, one stamp. The skills describe intent and hand-offs; the arithmetic of
263	// what version a repo is now at belongs here, where the update flows read it from.
264	async function main() {
265	  const argv = process.argv.slice(2);
266	  const flag = (name) => { const i = argv.indexOf(name); return i === -1 ? null : argv[i + 1] ?? null; };
267	  const targetRoot = flag('--target') ?? process.env.CLAUDINITE_REPO_ROOT ?? process.cwd();
268	  const dryRun = argv.includes('--dry-run');
269	  const consumed = new Set(['--target', targetRoot, '--dry-run', '--delivery', flag('--delivery')]);
270	  const ids = argv.filter((a) => !a.startsWith('--') && !consumed.has(a));
271	  if (!ids.length) {
272	    console.error('install: name at least one pack id — `node install.mjs --target <dir> <pack-id>…`');
273	    process.exitCode = 1;
274	    return;
275	  }
276	
277	  const r = await installPacks(targetRoot, ids, { dryRun, delivery: flag('--delivery') ?? 'auto-merge' });
