const token = process.env.GITHUB_TOKEN;
let i = 0;
while (true) {
  let merged = null, state = null;
  try {
    const res = await fetch('https://api.github.com/repos/missingbulb/NoRFinder/pulls/208', {
      headers: { Authorization: `token ${token}`, Accept: 'application/vnd.github+json' },
    });
    const json = await res.json();
    merged = json.merged;
    state = json.state;
  } catch { /* transient — retry */ }
  if (merged === true) { console.log('TERMINAL: PR #208 MERGED'); break; }
  if (state === 'closed') { console.log('TERMINAL: PR #208 CLOSED (unmerged)'); break; }
  i += 1;
  if (i % 6 === 0) console.log(`still open: state=${state} merged=${merged} (check #${i})`);
  await new Promise((r) => setTimeout(r, 20000));
}

